mapper.select:
select h.id as historyId, h.coupon_id as couponId, c.name as couponName, c.scope_type as scopeType, c.status as couponStatus, h.member_id as memberId, h.coupon_code as couponCode, h.get_type as getType, h.get_time as getTime, h.use_status as useStatus, h.use_time as useTime, h.order_sn as orderSn, h.start_time as startTime, h.end_time as endTime from sms_coupon_history h left join sms_coupon c on c.id = h.coupon_id
ifnull(h.del_flag, 0) = 0 and h.member_id = #{memberId} and h.coupon_id = #{couponId} and h.use_status = #{useStatus}
order by h.id desc

select o.id as orderId, o.order_sn as orderSn, o.member_id as memberId, o.mms_merchant_id as merchantId, o.product_quantity as quantity, o.pay_amount as pointsPrice, o.status as status, o.aftersale_status as aftersaleStatus, o.delivery_sn as deliverySn, o.payment_time as paymentTime, o.delivery_time as deliveryTime, o.receive_time as receiveTime, o.create_time as createTime, (select count(1) from oms_order_item i where i.order_id = o.id) as itemCount from oms_order o
o.order_type = 2 and o.biz_type is null and ifnull(o.del_flag, 0) = 0 and o.member_id = #{memberId} and o.order_sn = #{orderSn} and o.status = #{status}
order by o.id desc

select f.id as consumptionId, f.member_id as memberId, f.active_id as activityId, f.gift_id as giftId,
       g.gift_name as giftName, f.point as points, f.del_flag as delFlag, f.create_time as createTime
from ums_crowdfunding f
left join pms_gift g on g.id = f.gift_id

     and f.member_id = #{memberId}
     and f.gift_id = #{giftId}
     and f.active_id = #{activityId}

order by f.id desc
